import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI 通訊協定（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/uri-protocol.md","filePath":"zh-TW/user-guide/uri-protocol.md","lastUpdated":1786513079000}'),r={name:"zh-TW/user-guide/uri-protocol.md"};function c(s,e,l,n,i,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="uri-通訊協定-lertaro" tabindex="-1">URI 通訊協定（lertaro://） <a class="header-anchor" href="#uri-通訊協定-lertaro" aria-label="Permalink to &quot;URI 通訊協定（lertaro://）&quot;">​</a></h1><p>Lertaro 會自動把自己註冊為 <code>lertaro://</code> 連結的處理常式——不需要額外的安裝步驟，第一次執行時就會自動完成註冊。這樣任何能開啟連結的東西（瀏覽器、捷徑、別的程式、指令碼）都能直接跳到 Lertaro 的某個具體位置，而不是只能靠熱鍵觸發。</p><p>如果 Lertaro 還沒執行，開啟一個 <code>lertaro://</code> 連結會先啟動它，再執行這個連結指向的操作。如果已經在執行，正在執行的那個執行個體會直接處理這個連結——不會再啟動第二份處理程序。</p><h2 id="支援的連結" tabindex="-1">支援的連結 <a class="header-anchor" href="#支援的連結" aria-label="Permalink to &quot;支援的連結&quot;">​</a></h2><table tabindex="0"><thead><tr><th>連結</th><th>作用</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>啟用快速搜尋視窗——效果和用熱鍵叫出它一樣。</td></tr><tr><td><code>lertaro://search/[關鍵字]</code></td><td>啟用快速搜尋視窗，並預先帶入 <code>[關鍵字]</code>。</td></tr><tr><td><code>lertaro://fullsearch/[關鍵字]</code></td><td>開啟完整搜尋視窗，並預先帶入 <code>[關鍵字]</code>。</td></tr><tr><td><code>lertaro://settings/page/[分區]</code></td><td>開啟設定視窗，並切到指定的頂層分區。</td></tr><tr><td><code>lertaro://settings/entry/[序號]</code></td><td>開啟設定視窗，並直接跳轉到某一項具體設定，並高亮顯示。</td></tr><tr><td><code>lertaro://localsend</code></td><td>開啟空白的 LocalSend 傳送視窗。</td></tr><tr><td><code>lertaro://localsend/items[/編碼後的項目...]</code></td><td>切換到檔案/資料夾模式，並可按路徑段加入一個或多個項目。</td></tr><tr><td><code>lertaro://localsend/text[/編碼後的文字]</code></td><td>切換到文字模式，並可填入編碼後的文字。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>第一個會啟用快速搜尋視窗，並已經用「report」篩選好；第二個會直接開啟設定視窗的「外觀」頁。</p><p><code>[分區]</code> 對應側邊欄頂層的某一項：<code>Service</code>、<code>Index</code>、<code>General</code>、<code>Appearance</code>、<code>Hotkeys</code>、 <code>Plugins</code>、<code>Favorites</code>、<code>History</code>、<code>QuickPanel</code>、<code>About</code>——不區分大小寫。</p><p><code>[序號]</code> 不是給人手動輸入用的——它是<a href="./instant-answers.html">設定搜尋</a>在你選中某項設定結果時自己產生的一個數字，選中結果會自動帶上這個序號，原樣跳轉回那一項設定。這個序號在重新啟動之間並不穩定，不要指望某個具體數字每次都對應同一項設定。</p><h2 id="localsend-連結" tabindex="-1">LocalSend 連結 <a class="header-anchor" href="#localsend-連結" aria-label="Permalink to &quot;LocalSend 連結&quot;">​</a></h2><p>每個檔案/資料夾路徑或文字值都必須整體編碼為一個 URL 路徑段。加入多個項目時，為每個項目附加一個獨立的編碼路徑段；所有路徑都必須是已經存在的絕對路徑。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Ca.txt/D%3A%5CShared</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20world</span></span></code></pre></div><p><code>lertaro://localsend/items</code> 會開啟收集頁並切到檔案/資料夾模式，<code>lertaro://localsend/text</code> 則切到文字模式。帶有內容的連結會繼續進入裝置選擇，但絕不會自動選擇裝置或開始傳輸。如果傳送視窗已經開啟，這個連結不會執行任何操作，也不會改變視窗目前的內容或狀態。如果 LocalSend 尚未啟用，Lertaro 會改為開啟 LocalSend 設定頁。內容無效或過長時，整個要求都會被忽略。</p><h2 id="無法識別的連結" tabindex="-1">無法識別的連結 <a class="header-anchor" href="#無法識別的連結" aria-label="Permalink to &quot;無法識別的連結&quot;">​</a></h2><p>任何比對不上已知路由的連結——打錯了字、分區不存在、<code>lertaro://</code> 後面跟了一堆亂七八糟的內容——都會被直接忽略。由於任何網站或程式都能在你不知情的情況下叫用這個通訊協定，一個錯誤或異常的連結不應該產生任何出人意料的效果；這類情況只會記進記錄方便你自己排查，除此之外什麼都不會發生。</p>`,15)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
